var o=`0535-mutabbaq`;var t=`world-0535`;var i=`SA`;var a=`western-asia`;var l=8;var r=64;var u={en:`Mutabbaq`,ua:`Мутаббак`};var s={en:`A traditional dish from Saudi Arabia, centered on all-purpose flour, ground lamb, yellow onion, leek. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Саудівська Аравія. Основні складники: пшеничне борошно універсальне, фарш з ягнятини, жовта цибуля, цибуля-порей. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`all-purpose-flour`,390,`g`],[`water`,195,`ml`],[`table-salt`,5,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ground-lamb`,380,`g`],[`yellow-onion`,210,`g`],[`leek`,130,`g`],[`ground-cumin`,5,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:16,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 20 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 20 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:20,i:[[`sunflower-oil`,80,`ml`]]}];var g={slug:o,id:t,country:`SA`,region:a,servings:8,minutes:64,title:u,text:s,steps:d};export{i as country,g as default,t as id,r as minutes,a as region,l as servings,o as slug,d as steps,s as text,u as title};